/**
 * T10_F375 „Das Netz als Karte“ (6.4, 6.6): the small, quiet line of the map. What Luna knows in
 * this mode („1.240 Einträge · 38 Felder · 12 neu seit gestern“, only with the capability
 * knowledge-graph-growth), or a search's glow line while his words glow. T10_F592 (universe U554):
 * the line lies on the map's top left corner, so the map keeps the whole height; it names the mode
 * when it is not the first one, and a glow line has a small × that empties the search. Where the
 * line does not fit, its „neu“ part goes first (screen readers still hear it); a word is never cut. On the phone the page's i
 * stands right after it (`onInfo`); on a wide window the i is in the bar (src/screens/Memory.tsx).
 */

import { useLayoutEffect, useRef, useState } from "preact/hooks";
import { T } from "../../text";
import { CloseIcon, InfoIcon } from "../icons";

/** The line without its last part when that part tells what is new; null when there is none. */
export function withoutNew(text: string): string | null {
  const parts = text.split(" · ");
  return parts.length > 1 && /\bneu\b/.test(parts[parts.length - 1]!) ? parts.slice(0, -1).join(" · ") : null;
}

}

.net__clear svg {
  width: 16px;
  height: 16px;
}

/* The page's i on the phone, right after the line: the app's (i) (U267) as a small sign with a
   whole finger's target. */
.icon-button.net__info {
  flex: none;
  width: 44px;
  height: 44px;
  margin: -8px 0 -8px -10px;
  border-radius: 50%;
  pointer-events: auto;
}

.net__info svg {
  width: 16px;
  height: 16px;
}

/* The line's whole width, measured out of sight (the „neu“ part goes when it does not fit). */
.net__measure {
  position: absolute;
  /** A memory node's „In Erinnerungen zeigen“. */
  onShow?: (words: string) => void;
  /** T10_F592: the glow line's ×, which empties the page's search. */
  onClear?: () => void;
  /** T10_F592: the mode's name on the map's line when it is not the first mode. */
  place?: string | null;
  /** T10_F592: the net takes the keyboard's focus when it comes (after his „Im Netz zeigen“). */
  takeFocus?: boolean;
  /** T10_F592: on the phone the page's i, right after the map's line. */
  onInfo?: () => void;
}

export function KnowledgeNet({ mode, source = "knowledge", typed, onShow, onClear, place = null, takeFocus = false, onInfo }: NetProps) {

