23	import { isNew } from "../state/netGrowth";
24	import { arrivalsOf, connectionsOf, expansionOf, idsOf, type Layer } from "../state/netLayers";
25	import { regionsOf } from "../state/netMap";
26	import { boundsOf, type Camera, fitPoints, focusPoint, zoomOfLevel } from "../state/netZoom";
27	import { MAP_PAD } from "../state/territories";
28	import { wide } from "../state/layout";
29	import { navigate } from "../state/router";
30	import { toast } from "../state/toasts";
31	import { T } from "../text";
32	import { EmptyState } from "./EmptyState";
33	import { BookCalmIcon } from "./icons";
34	import { Failure } from "./KnowledgeFailure";
