/**
 * T10_F336 (the universe plan's U320), rebuilt by T10_F375 „Das Netz als Karte“ (decodeux's order
 * Part 6): the tab Netz of Wissen as a map of her knowledge. The most significant nodes are laid
 * out once in the map's real shape with their fields as regions (src/state/graphLayout.ts); the map
 * zooms and moves like a map (src/screens/net/useCamera.ts) with semantic levels
 * (src/screens/net/NetMap.tsx). A tap opens the node's entry (a sheet on the phone, a panel on the
 * desktop, src/screens/net/NetEntry.tsx) and lets its neighbours bloom out of it; „zurück“ takes
 * the last ones away again. Typing a topic keeps the map and flies to the hits, which glow by
 * match times significance; the arrow keys walk them. The header line counts what she knows and
 * what is new, and new knowledge blooms in while the map is open (src/screens/net/useGrowth.ts).
 * The canvas answers at once; the entries load after (U021's rule). T10_F576 (universe U520): the
 * same map draws the memory net (`source` memory), and the search field is Gedächtnis' own.
 * T10_F592 (universe U554): the map fills the page edge to edge; its line lies on the map.
 *
 * Replaces T9_F371's fixed viewBox, stretched square and always-on touch-action: none.
 */

import { useEffect, useMemo, useRef, useState } from "preact/hooks";
import { layout } from "../state/graphLayout";
import { insertIntoComposer } from "../state/composer";
