/**
 * T10_F576 (universe U520): Gedächtnis, one page for what Luna remembers and what she knows (routes
 * #/memory and #/wiki, #/wiki/<mode>; a wiki page #/wiki/<mode>/<slug> stays its own screen).
 * T10_F592 (universe U554, decodeux's optimum of 2026-10-21): the net is the page. One row, the bar
 * itself, holds the segment „Erinnerungen“ | „Wissen“, the magnifier and the filter (on the phone
 * after the back arrow, with no visible title; on a wide window after the title, with the i at
 * the end); the segment decides which net fills the rest of the screen edge to edge
 * (the memory net or the knowledge net, T10_F575's map, src/screens/KnowledgeNet.tsx). The
 * magnifier opens every way to search and edit that part (Erinnerungen, T8_F075: the search, a day
 * to look back to, Einträge and Verlauf, Vergessen, the undo and the people, T12_F461; Wissen,
 * T8_F077 and T9_F134: the wiki's pages and what she collected, src/screens/Wiki.tsx), and its
 * words glow in the net with „Im Netz zeigen“. The filter is one dropdown of the modes
 * (the app's FilterMenu with the filter icon); the page's first line and the net's help stand behind
 * the bar's i, on the phone behind a small i right after the map's line (and the first line
 * for screen readers at the page's start). A part without its net shows its lists at once, a part
 * without lists has no magnifier. Each part shows only with its capability.
 *
 * Replaces T10_F576's first line on the page, its third segment „Netz“, the inner switch between
 * the nets, the row of mode chips and the net's own i.
 *
 * A sealed mode's answers live in this component's state only, and go when the screen closes
 * (src/state/memory.ts caches open modes only); the memory net never shows a sealed mode: its
 * filter offers the same modes as the lists and marks a sealed one „nur in der Liste“.
 */

import { useEffect, useState } from "preact/hooks";
import type { MemoryEntry, MemoryHistoryItem } from "@luna/kit/client";
import { Button, Input } from "@luna/kit/preact";
import { InfoSheet } from "../components/InfoButton";
import { SegmentBar } from "../components/SegmentBar";
import { available } from "../state/connection";
import { wide } from "../state/layout";
import type { NetSource } from "../state/knowledgeNet";
import {
  actionLabel,
  entryMeta,
  forgetEntry,
  germanDate,
  historyTime,
  isSealedMode,
  kindLabel,
  loadEntries,
  loadHistory,
  memoryFailure,
  memoryModes,
  undoLast,
} from "../state/memory";
import { refreshPresence, unlocked } from "../state/presence";
import { toast } from "../state/toasts";
import { T } from "../text";
import { Screen } from "./Bar";
import { ConfirmSheet } from "./Confirm";
import { FilterMenu } from "./FilterMenu";
import { EmptyState } from "./EmptyState";
import { FilterIcon, InfoIcon, LockIcon, MemoryCalmIcon, NetIcon, SearchCalmIcon, SearchIcon } from "./icons";
import { Failure } from "./KnowledgeFailure";
import { More, usePaged } from "./usePaged";
import { KnowledgeNet } from "./KnowledgeNet";
import { Knowledge } from "./Wiki";
import { peopleOffered } from "../state/people";
import { navigate, route } from "../state/router";
import { WIKI_MODES } from "../state/wiki";
import { displayMode } from "../state/modes";
import { Skeleton } from "../components/Skeleton";

/** The search is sent this long after the last key. */
const SEARCH_DELAY_MS = 300;

type Tab = "entries" | "history";
type Part = "memories" | "knowledge";
type View = "net" | "list";

/** The mode and the part last chosen, for the next visit this session (never a sealed mode). */
let lastMode = "general";
let lastPart: Part | null = null;

/** A failed forget or undo as one toast; "nothing to undo" is news, not an error (O17). */
function failureToast(error: unknown): void {
  const found = memoryFailure(error);
  if (!found) return;
  if (found.kind === "asleep") toast(T.memory.asleep, "error");
  else if (found.kind === "locked") toast(T.memory.locked, "error");
  else toast(found.sentence, found.sentence === T.memory.nothingToUndo ? "info" : "error");
}

function EntryRow({ entry, readOnly, onForget }: { entry: MemoryEntry; readOnly: boolean; onForget: (entry: MemoryEntry) => void }) {
  return (
    <li class="memory-entry" data-testid="memory-entry" data-id={entry.id}>
      <div class="memory-entry__body">
        <span class="memory-entry__kind" data-kind={entry.kind}>
          {kindLabel(entry.kind)}
        </span>
        <p class="memory-entry__text">{entry.text ?? T.memory.lockedText}</p>
        <p class="memory-entry__meta">{entryMeta(entry)}</p>
      </div>
      {readOnly ? null : (
        <Button size="small" variant="ghost" onClick={() => onForget(entry)}>
          {T.memory.forget}
        </Button>
      )}
    </li>
  );
}

function HistoryRow({ item }: { item: MemoryHistoryItem }) {
  return (
    <li class="memory-entry" data-testid="memory-history-item" data-action={item.action}>
      <div class="memory-entry__body">
        <p class="memory-entry__meta">
          <time dateTime={item.time}>{historyTime(item.time)}</time> · <span class="memory-entry__action">{actionLabel(item.action)}</span>
        </p>
        <p class="memory-entry__text">{item.text ?? T.memory.lockedText}</p>
      </div>
    </li>
  );
}

function Entries({ mode, q, asOf }: { mode: string; q: string; asOf: string | null }) {
  const paged = usePaged((cursor, signal) => loadEntries(mode, q, asOf, cursor, signal).then((page) => ({ rows: page.entries, next: page.next })), memoryFailure, [mode, q, asOf]);
  const { view, failure, loading } = paged;
  const [forgetting, setForgetting] = useState<MemoryEntry | null>(null);
  const [busy, setBusy] = useState(false);
  const act = async (work: () => Promise<void>) => {
    setBusy(true);
    try {
      await work();
    } catch (error) {
      failureToast(error);
    } finally {
      setBusy(false);
      setForgetting(null);
    }
  };
  const forget = (entry: MemoryEntry) =>
    act(async () => {
      await forgetEntry(entry);
      paged.drop((e) => e.id === entry.id);
      toast(T.memory.forgotten, "success");
    });
  const undo = () =>
    act(async () => {
      toast(T.memory.undone(await undoLast(mode)), "success");
      paged.reload();
    });
  const readOnly = asOf !== null;
  const entries = view?.rows ?? [];
  return (
    <>
      {!readOnly && !failure ? (
        <div class="live-tools">
          <span />
          <Button size="small" disabled={busy} onClick={() => void undo()}>
            {T.memory.undo}
          </Button>
        </div>
      ) : null}
      {failure ? <Failure failure={failure} onAwake={paged.reload} /> : null}
      {!failure && loading && entries.length === 0 ? <Skeleton shape="rows" /> : null}
      {!failure && !loading && entries.length === 0 ? <EmptyState icon={q ? SearchCalmIcon : MemoryCalmIcon} words={q ? T.empty.found : T.empty.memory} sentence={q ? T.memory.emptySearch : T.memory.empty} /> : null}
      <ul class="memory-list" data-testid="memory-entries">
        {entries.map((entry) => (
          <EntryRow key=[REDACTED] entry={entry} readOnly={readOnly} onForget={setForgetting} />
        ))}
      </ul>
      <More paged={paged} label={T.memory.more} />
      <ConfirmSheet
        open={forgetting !== null}
        question={T.memory.forgetConfirm}
        confirm={T.memory.forget}
        cancel={T.memory.cancel}
        busy={busy}
        onConfirm={() => forgetting && void forget(forgetting)}
        onClose={() => setForgetting(null)}
        testId="memory-forget"
      >
        <p class="memory-entry__text">{forgetting?.text}</p>
        <p class="placeholder">{T.memory.forgetHint}</p>
      </ConfirmSheet>
    </>
  );
}

function History({ mode }: { mode: string }) {
  const paged = usePaged((cursor) => loadHistory(mode, cursor).then((page) => ({ rows: page.items, next: page.next })), memoryFailure, [mode]);
  const { failure, loading } = paged;
  const items = paged.view?.rows ?? [];
  return (
    <>
      {failure ? <Failure failure={failure} onAwake={paged.reload} /> : null}
      {!failure && loading && items.length === 0 ? <Skeleton shape="rows" /> : null}
      {!failure && !loading && items.length === 0 ? <EmptyState icon={MemoryCalmIcon} words={T.memory.emptyHistory} small /> : null}
      <ul class="memory-list" data-testid="memory-history">
        {items.map((item, i) => (
          <HistoryRow key=[REDACTED] item={item} />
        ))}
      </ul>
      <More paged={paged} label={T.memory.more} />
    </>
  );
}

/** Erinnerungen: the people, the day to look back to, Einträge and Verlauf. */
function Memories({ mode, q }: { mode: string; q: string }) {
  const [tab, setTab] = useState<Tab>("entries");
  const [asOf, setAsOf] = useState<string | null>(null);
  return (
    <>
      <div class="memory-tools">
        <SegmentBar items={(["entries", "history"] as Tab[]).map((t) => ({ id: t, label: T.memory.tabs[t]! }))} value={tab} onChange={(id) => setTab(id as Tab)} label={T.memory.tabsLabel} testId="memory-tabs" />
        <label class="memory-date">
          <span class="luna-field__label">{T.memory.asOf}</span>
          <input class="luna-input" type="date" data-testid="memory-as-of" value={asOf ?? ""} onChange={(event) => setAsOf(event.currentTarget.value || null)} />
        </label>
      </div>
      {peopleOffered() ? (
        // T12_F461: the people in his life.
        <Button size="small" variant="secondary" class="memory-people" onClick={() => navigate({ name: "people" })} data-testid="memory-people">
          {T.people.open}
        </Button>
      ) : null}
      {asOf ? (
        <div class="notice memory-banner" role="status" data-testid="memory-banner">
          <p>
            <strong>{T.memory.asOfBanner(germanDate(asOf))}</strong> {T.memory.asOfNote}
          </p>
          <Button size="small" onClick={() => setAsOf(null)}>
            {T.memory.asOfClear}
          </Button>
        </div>
      ) : null}
      {tab === "entries" ? <Entries key=[REDACTED] mode={mode} q={q} asOf={asOf} /> : <History key=[REDACTED] mode={mode} />}
    </>
  );
}

/** The parts this assistance offers, in their order; each is a net and, behind the magnifier, its lists. */
function partsOffered(): Part[] {
  const parts: Part[] = [];
  if (available("memory") || available("memoryNet")) parts.push("memories");
  if (available("wiki") || available("knowledge") || available("sourceRegister") || available("knowledgeNet")) parts.push("knowledge");
  return parts;
}

/** The net a part draws, when this assistance offers it. */
function netOf(part: Part): NetSource | null {
  if (part === "memories") return available("memoryNet") ? "memory" : null;
  return available("knowledgeNet") ? "knowledge" : null;
}

/**
 * Whether a part has lists to search and edit behind the magnifier; without them no magnifier.
 * (Today's capabilities always pair them: memoryNet needs memories, knowledgeNet needs knowledge.)
 */
function listsOf(part: Part): boolean {
  return part === "memories" ? available("memory") : available("knowledge") || available("wiki") || available("sourceRegister");
}

/**
 * T10_F592: what he sees, behind the bar's i on a wide window and behind the i after the map's line
 * on the phone: the page's first line, the net's help, one sentence per tool of the part he is on,
 * and whom the net is shown to; the magnifier's sentence only where the magnifier is (net and lists).
 * U267: they stand in the sheet of every other (i) (components/InfoButton).
 */
function infoSentences(net: NetSource | null, part: Part, lists: boolean, filter: boolean): string[] {
  const tools = [lists && net ? (part === "memories" ? T.net.page.searchMemories : T.net.page.searchKnowledge) : null, lists && net ? T.net.page.glow : null, filter ? T.net.page.filter : null].filter(Boolean).join(" ");
  return [
    T.net.page.about,
    net ? (net === "memory" ? T.net.helpMemory : T.net.help) : null,
    tools || null,
    part === "memories" && filter ? T.memory.general : null,
    net ? (net === "memory" ? T.net.privacyMemory : T.net.privacy) : null,
  ].filter((sentence): sentence is string => sentence !== null);
}

export function Memory() {
  const current = route.value;
  const parts = partsOffered();
  const [chosenPart, setPart] = useState<Part>(() => (current.name === "wiki" ? "knowledge" : (lastPart ?? "memories")));
  const part = parts.includes(chosenPart) ? chosenPart : (parts[0] ?? "memories");
  const net = netOf(part);
  const lists = listsOf(part);
  // T10_F592: the net is the page; the magnifier opens the lists (#/wiki, the wiki page's way back, opens them too).
  const [searching, setSearching] = useState(current.name === "wiki");
  const view: View = net && (!searching || !lists) ? "net" : "list";
  const [info, setInfo] = useState(false);
  // Whether the net takes the keyboard's focus when it comes: only after his „Im Netz zeigen“.
  const [arrive, setArrive] = useState(false);
  const [chosen, setMode] = useState(current.name === "wiki" && current.mode ? current.mode : lastMode);
  const [typed, setTyped] = useState("");
  const [q, setQ] = useState("");
  // Whether the sealed modes may be offered: GET /health says unlocked (O14), asked on open.
  useEffect(() => {
    void refreshPresence();
  }, []);
  // Erinnerungen offer a sealed mode while it is unlocked, in the net and in the lists alike; the
  // memory net never draws one (section 30.2): there the filter marks it „nur in der Liste“, and
  // choosing it opens the lists.
  const modes = part === "memories" ? memoryModes(lists && unlocked.value) : WIKI_MODES.value;
  // A sealed mode that locked while chosen falls back to the first mode (general); T12_F275: so
  // does a mode this assistance does not show, before anything is asked for it.
  const mode = modes.includes(chosen) ? chosen : (modes[0] ?? "general");
  useEffect(() => {
    const timer = setTimeout(() => setQ(typed.trim()), SEARCH_DELAY_MS);
    return () => clearTimeout(timer);
  }, [typed]);
  const choose = (next: string) => {
    setArrive(false);
    setMode(next);
    if (!isSealedMode(next)) lastMode = next;
    else if (lists) setSearching(true);
  };
  /** Back to the net: a sealed mode stays in the lists, so the net shows the last open one. */
  const toNet = (glow: boolean) => {
    if (isSealedMode(mode)) setMode(lastMode);
    setArrive(glow);
    setSearching(false);
  };
  const choosePart = (next: string) => {
    setArrive(false);
    lastPart = next as Part;
    setPart(next as Part);
  };
  const show = (words: string) => {
    choosePart("memories");
    setTyped(words);
    setSearching(true);
  };
  const searchToggle = net && lists ? (
    <button
      type="button"
      class="icon-button memory-nav__search"
      data-testid="memory-search"
      aria-label={searching ? T.net.page.closeSearch : T.net.page.openSearch}
      title={searching ? T.net.page.closeSearch : T.net.page.openSearch}
      onClick={() => (searching ? toNet(false) : setSearching(true))}
    >
      {searching ? <NetIcon /> : <SearchIcon />}
    </button>
  ) : null;
  const sealedMark =
    view === "net" ? (
      <>
        <span class="filter-menu__note">{T.net.page.listOnly}</span>
        <LockIcon />
      </>
    ) : (
      <LockIcon />
    );
  const phone = !wide.value;
  const infoButton = (
    <button type="button" class="icon-button" data-testid="memory-info" aria-label={T.info.open(T.net.page.infoTitle)} title={T.net.page.infoTitle} aria-haspopup="dialog" onClick={() => setInfo(true)}>
      <InfoIcon />
    </button>
  );
  // T10_F592: one row, in the bar itself: the segment, the magnifier and the filter (on the phone
  // with the back arrow before it; its i stands after the map's line there).
  const nav = (
    <div class="memory-nav" data-testid="memory-nav">
      {parts.length > 1 ? <SegmentBar items={parts.map((id) => ({ id, label: T.memory.parts[id]! }))} value={part} onChange={choosePart} label={T.memory.partsLabel} testId="memory-parts" /> : <span class="memory-nav__space" />}
      {searchToggle}
      {modes.length > 1 ? (
        <FilterMenu
          label={T.memory.modes}
          options={modes.map((m) => ({ value: m, label: displayMode(m), ...(isSealedMode(m) ? { mark: sealedMark } : {}) }))}
          chosen={[mode]}
          onChange={(next) => next[0] && choose(next[0])}
          icon={FilterIcon}
          required
          testId="mode-picker"
        />
      ) : null}
      {phone ? null : infoButton}
    </div>
  );
  return (
    <Screen
      title={T.memory.title}
      class={view === "net" ? "memory-screen memory-screen--net" : "memory-screen"}
      refresh="remount"
      actions={nav}
      row={phone}
      {...(phone ? { back: { name: "chats" } as const } : {})}
    >
      <InfoSheet open={info} onClose={() => setInfo(false)} title={T.net.page.infoTitle} sentences={infoSentences(net, part, lists, modes.length > 1)} testId="memory-info-sheet" />
      <div class="memory" data-testid="memory" data-mode={mode} data-part={part} data-view={view}>
        {view === "net" && net ? (
          <KnowledgeNet key=[REDACTED] mode={mode} source={net} typed={typed} onShow={show} onClear={() => setTyped("")} place={mode === modes[0] ? null : displayMode(mode)} takeFocus={arrive} {...(phone ? { onInfo: () => setInfo(true) } : {})} />
        ) : (
          <>
            <div class="memory-find">
              <Input value={typed} onValue={setTyped} ariaLabel={T.memory.search} placeholder={T.memory.placeholder} type="search" />
              {net && typed.trim() ? (
                <Button size="small" variant="secondary" data-testid="memory-show-net" onClick={() => toNet(true)}>
                  {T.net.page.showInNet}
                </Button>
              ) : null}
              {/* T10_F605 (review round 2): on the phone the bar has no room; the list view's i stands beside the search. */}
              {phone ? infoButton : null}
            </div>
            {part === "memories" ? available("memory") ? <Memories key=[REDACTED] mode={mode} q={q} /> : null : <Knowledge key=[REDACTED] mode={mode} q={q} typed={typed} />}
          </>
        )}
      </div>
    </Screen>
  );
}

/**
