/** The search is sent this long after the last key. */
const SEARCH_DELAY_MS = 300;

type Tab = "entries" | "history";
type Part = "memories" | "knowledge";
type View = "net" | "list";

/** The mode and the part last chosen, for the next visit this session (never a sealed mode). */
let lastMode = "general";
let lastPart: Part | null = null;

/** A failed forget or undo as one toast; "nothing to undo" is news, not an error (O17). */
function failureToast(error: unknown): void {
  const found = memoryFailure(error);
  if (!found) return;
  if (found.kind === "asleep") toast(T.memory.asleep, "error");
  else if (found.kind === "locked") toast(T.memory.locked, "error");
  else toast(found.sentence, found.sentence === T.memory.nothingToUndo ? "info" : "error");
}

function EntryRow({ entry, readOnly, onForget }: { entry: MemoryEntry; readOnly: boolean; onForget: (entry: MemoryEntry) => void }) {
  return (
    <li class="memory-entry" data-testid="memory-entry" data-id={entry.id}>
      <div class="memory-entry__body">
        <span class="memory-entry__kind" data-kind={entry.kind}>
          {kindLabel(entry.kind)}
        </span>
        <p class="memory-entry__text">{entry.text ?? T.memory.lockedText}</p>
        <p class="memory-entry__meta">{entryMeta(entry)}</p>
      </div>
      {readOnly ? null : (
        <Button size="small" variant="ghost" onClick={() => onForget(entry)}>
          {T.memory.forget}
        </Button>
      )}
    </li>
  );
}

function HistoryRow({ item }: { item: MemoryHistoryItem }) {
  return (
    <li class="memory-entry" data-testid="memory-history-item" data-action={item.action}>
      <div class="memory-entry__body">
        <p class="memory-entry__meta">
          <time dateTime={item.time}>{historyTime(item.time)}</time> · <span class="memory-entry__action">{actionLabel(item.action)}</span>
        </p>
        <p class="memory-entry__text">{item.text ?? T.memory.lockedText}</p>
      </div>
    </li>
  );
}

function Entries({ mode, q, asOf }: { mode: string; q: string; asOf: string | null }) {
  const paged = usePaged((cursor, signal) => loadEntries(mode, q, asOf, cursor, signal).then((page) => ({ rows: page.entries, next: page.next })), memoryFailure, [mode, q, asOf]);
  const { view, failure, loading } = paged;
  const [forgetting, setForgetting] = useState<MemoryEntry | null>(null);
  const [busy, setBusy] = useState(false);
  const act = async (work: () => Promise<void>) => {
    setBusy(true);
    try {
      await work();
    } catch (error) {
      failureToast(error);
    } finally {
      setBusy(false);
      setForgetting(null);
    }
  };
  const forget = (entry: MemoryEntry) =>
    act(async () => {
      await forgetEntry(entry);
      paged.drop((e) => e.id === entry.id);
      toast(T.memory.forgotten, "success");
    });
  const undo = () =>
    act(async () => {
      toast(T.memory.undone(await undoLast(mode)), "success");
      paged.reload();
    });
  const readOnly = asOf !== null;
  const entries = view?.rows ?? [];
  return (
    <>
      {!readOnly && !failure ? (
        <div class="live-tools">
          <span />
          <Button size="small" disabled={busy} onClick={() => void undo()}>
            {T.memory.undo}
          </Button>
        </div>
      ) : null}
      {failure ? <Failure failure={failure} onAwake={paged.reload} /> : null}
      {!failure && loading && entries.length === 0 ? <Skeleton shape="rows" /> : null}
      {!failure && !loading && entries.length === 0 ? <EmptyState icon={q ? SearchCalmIcon : MemoryCalmIcon} words={q ? T.empty.found : T.empty.memory} sentence={q ? T.memory.emptySearch : T.memory.empty} /> : null}
      <ul class="memory-list" data-testid="memory-entries">
        {entries.map((entry) => (
          <EntryRow key=[REDACTED] entry={entry} readOnly={readOnly} onForget={setForgetting} />
        ))}
      </ul>
      <More paged={paged} label={T.memory.more} />
      <ConfirmSheet
        open={forgetting !== null}
        question={T.memory.forgetConfirm}
        confirm={T.memory.forget}
        cancel={T.memory.cancel}
        busy={busy}
        onConfirm={() => forgetting && void forget(forgetting)}
        onClose={() => setForgetting(null)}
        testId="memory-forget"
      >
        <p class="memory-entry__text">{forgetting?.text}</p>
        <p class="placeholder">{T.memory.forgetHint}</p>
      </ConfirmSheet>
    </>
  );
}

function History({ mode }: { mode: string }) {
  const paged = usePaged((cursor) => loadHistory(mode, cursor).then((page) => ({ rows: page.items, next: page.next })), memoryFailure, [mode]);
  const { failure, loading } = paged;
  const items = paged.view?.rows ?? [];
  return (
    <>
      {failure ? <Failure failure={failure} onAwake={paged.reload} /> : null}
      {!failure && loading && items.length === 0 ? <Skeleton shape="rows" /> : null}
      {!failure && !loading && items.length === 0 ? <EmptyState icon={MemoryCalmIcon} words={T.memory.emptyHistory} small /> : null}
      <ul class="memory-list" data-testid="memory-history">
        {items.map((item, i) => (
          <HistoryRow key=[REDACTED] item={item} />
        ))}
      </ul>
      <More paged={paged} label={T.memory.more} />
    </>
  );
}

