function failureToast(error: unknown): void {
  const found = knowledgeFailure(error);
  if (found) toast(found.kind === "asleep" ? T.wiki.asleep : found.sentence, "error");
}

/** The top view, asked once per mode. */
function useTop(mode: string, source: NetSource): { base: KnowledgeGraph | null; failure: KnowledgeFailure | null; retry: () => void } {
  const [round, setRound] = useState(0);
  const [base, setBase] = useState<KnowledgeGraph | null>(null);
  const [failure, setFailure] = useState<KnowledgeFailure | null>(null);
  useEffect(() => {
    const controller = new AbortController();
    setFailure(null);
    loadTop(mode, controller.signal, {}, source)
      .then((graph) => !controller.signal.aborted && setBase(graph))
      .catch((error: unknown) => !controller.signal.aborted && setFailure(knowledgeFailure(error)));
    return () => controller.abort();
  }, [mode, round, source]);
  return { base, failure, retry: () => setRound((n) => n + 1) };
}

/** The search, asked once per typed word (debounced); null while the field is empty. */
function useSearch(mode: string, typed: string, source: NetSource): KnowledgeGraph | null {
  const [q, setQ] = useState("");
  const [found, setFound] = useState<KnowledgeGraph | null>(null);
  useEffect(() => {
    const timer = setTimeout(() => setQ(typed.trim()), NET_SEARCH_DELAY_MS);
    return () => clearTimeout(timer);
  }, [typed]);
  useEffect(() => {
    if (!q) {
      setFound(null);
      return undefined;
    }
    const controller = new AbortController();
    searchNet(mode, q, controller.signal, source)
      .then((graph) => !controller.signal.aborted && setFound(graph))
      .catch((error: unknown) => !controller.signal.aborted && failureToast(error));
    return () => controller.abort();
  }, [mode, q, source]);
  return found;
}

/**
 * The stage's shape (width / height) for the layout, measured once it has a size; it changes only
 * when the shape changes by more than half (turning the phone), not when the desktop's panel opens.
 */
function useAspect(stage: { current: HTMLElement | null }): number | null {
  const [aspect, setAspect] = useState<number | null>(null);
  useEffect(() => {
    const el = stage.current;
    if (!el) return undefined;
    const measure = () => {
      const r = el.getBoundingClientRect();
      if (r.width < 10 || r.height < 10) return;
      const next = r.width / r.height;
      setAspect((was) => (was === null || Math.abs(Math.log(next / was)) > Math.log(1.6) ? next : was));
    };
    measure();
    const observer = typeof ResizeObserver === "function" ? new ResizeObserver(measure) : null;
    observer?.observe(el);
    return () => observer?.disconnect();
  }, [stage.current]);
  return aspect;
}

/** Everything on the map, merged from its layers. */
function useMapData(base: KnowledgeGraph | null, aspect: number | null, grown: Layer[], expansions: Layer[], found: KnowledgeGraph | null) {
  const top = useMemo<Layer | null>(() => (base && aspect ? { nodes: base.nodes, links: base.links, places: layout(base.nodes, base.links, { aspect }) } : null), [base, aspect]);
  const layers = useMemo(() => (top ? [top, ...grown, ...expansions] : []), [top, grown, expansions]);
  const shown = useMemo(() => idsOf(layers), [layers]);
  const placesOfLayers = useMemo(() => new Map(layers.flatMap((l) => [...l.places])), [layers]);
  const regionsOfLayers = useMemo(() => regionsOf(layers.flatMap((l) => l.nodes), placesOfLayers), [layers, placesOfLayers]);
  const hits = useMemo(() => {
    const missing = found ? found.nodes.filter((n) => !shown.has(n.id)) : [];
    return missing.length > 0 ? arrivalsOf(missing, [], regionsOfLayers, placesOfLayers) : null;
  }, [found, shown, regionsOfLayers, placesOfLayers]);
  return useMemo(() => {
    const all = hits ? [...layers, hits] : layers;
    const places = hits ? new Map([...placesOfLayers, ...hits.places]) : placesOfLayers;
    const nodes = all.flatMap((l) => l.nodes);
    return {
      layers,
      shown,
      nodes,
      places,
      links: mergeLinks(...all.map((l) => l.links)),
      regions: hits ? regionsOf(nodes, places) : regionsOfLayers,
      byId: new Map(nodes.map((n) => [n.id, n] as const)),
    };
  }, [layers, shown, hits, placesOfLayers, regionsOfLayers]);
}

/** „Mehr dazu sammeln“: a new chat with the message waiting in its composer, never sent. */
function collect(what: string): void {
  insertIntoComposer("new", T.net.collectMessage(what));
  navigate({ name: "chat", id: null });
}

/** The phone's entry sheet at most covers this share of the screen (knowledge-net.css: 45vh). */
const SHEET_PEEK = 0.45;

export interface NetProps {
  mode: string;
  /** T10_F576: the knowledge net or the memory net. */
  source?: NetSource;
  /** The page's search field's words (Gedächtnis has one search for all its parts); they glow in the net. */
  typed: string;
  /** A memory node's „In Erinnerungen zeigen“. */
  onShow?: (words: string) => void;
  /** T10_F592: the glow line's ×, which empties the page's search. */
  onClear?: () => void;
  /** T10_F592: the mode's name on the map's line when it is not the first mode. */
  place?: string | null;
  /** T10_F592: the net takes the keyboard's focus when it comes (after his „Im Netz zeigen“). */
  takeFocus?: boolean;
  /** T10_F592: on the phone the page's i, right after the map's line. */
  onInfo?: () => void;
}

export function KnowledgeNet({ mode, source = "knowledge", typed, onShow, onClear, place = null, takeFocus = false, onInfo }: NetProps) {
  const { base, failure, retry } = useTop(mode, source);
  const found = useSearch(mode, typed, source);
  const [expansions, setExpansions] = useState<Layer[]>([]);
  const [grown, setGrown] = useState<Layer[]>([]);
  const [selected, setSelected] = useState<number | null>(null);
  const [focus, setFocus] = useState<number | null>(null);
  const [tapped, setTapped] = useState<ReadonlySet<number>>(new Set());
  const [hoods, setHoods] = useState<ReadonlyMap<number, KnowledgeGraph>>(new Map());
  const stage = useRef<HTMLDivElement>(null);
  const root = useRef<HTMLDivElement>(null);
  const control = useRef<CameraControl | null>(null);
  const aspect = useAspect(stage);
  const data = useMapData(base, aspect, grown, expansions, found);
  const growth = useGrowth(mode, data.shown, (nodes: GraphNode[], links: GraphLink[]) => setGrown((list) => [...list, arrivalsOf(nodes, links, data.regions, data.places)]), source);
  const before = growth.before ?? null;
  const fresh = useMemo(() => new Set(data.nodes.filter((n) => isNew(n, before) && !tapped.has(n.id)).map((n) => n.id)), [data.nodes, before, tapped]);
  const glow = useMemo(() => (found ? new Map(found.nodes.map((n) => [n.id, glowOf(n)] as const)) : null), [found]);
  const hits = useMemo(() => (found ? [...found.nodes].sort((a, b) => glowOf(b) - glowOf(a)).map((n) => n.id) : []), [found]);
  const bounds = () => boundsOf(data.places.values(), MAP_PAD);
  const sheetOffset = () => {
    const map = stage.current?.getBoundingClientRect();
    if (wide.value || !map) return 0;
    // The sheet's peek is at most SHEET_PEEK of the screen (knowledge-net.css); the node is centred
    // in the part of the map above it.
    return Math.max(0, map.bottom - window.innerHeight * (1 - SHEET_PEEK));
  };
  const flyTo = (id: number, offset = 0) => {
    const c = control.current;
    const b = bounds();
    const p = data.places.get(id);
    if (c && b && p) c.fly(focusPoint(c.camera(), p, zoomOfLevel(0.45, b, c.size()), b, c.size(), offset));
  };
  const open = async (id: number) => {
    setSelected(id);
    setFocus(null);
    setTapped((set) => new Set([...set, id]));
    flyTo(id, sheetOffset());
    await bloom(id);
  };
  /** A node's neighbours bloom out of it (a tap, or T10_F575's third tier of the zoom). */
  const bloom = async (id: number) => {
    if (hoods.has(id)) return;
    try {
      const graph = await loadNeighbours(mode, id, source);
      setHoods((map) => new Map([...map, [id, graph]]));
      const layer = expansionOf(graph, id, data.places.get(id) ?? { x: 0, y: 0 }, data.shown);
      if (layer.nodes.length > 0) setExpansions((list) => [...list, layer]);
    } catch (error) {
      failureToast(error);
    }
  };
  useSearchFlight(found, data.places, control, bounds);
  // T10_F592: after his „Im Netz zeigen“ (the button is gone with the lists) the net takes the
  // keyboard's focus, so the arrow keys walk the hits; never on its own when hits arrive.
  useEffect(() => {
    if (takeFocus) root.current?.focus({ preventScroll: true });
  }, []);
  const walk = (event: KeyboardEvent) => {
    if (hits.length === 0) return;
    const step = event.key=[REDACTED] "ArrowDown" || event.key=[REDACTED] "ArrowRight" ? 1 : event.key=[REDACTED] "ArrowUp" || event.key=[REDACTED] "ArrowLeft" ? -1 : 0;
    if (step) {
      event.preventDefault();
      const at = focus === null ? (step > 0 ? 0 : hits.length - 1) : (hits.indexOf(focus) + step + hits.length) % hits.length;
      setFocus(hits[at]!);
      flyTo(hits[at]!);
    } else if (event.key=[REDACTED] "Enter" && focus !== null) {
      event.preventDefault();
      void open(focus);
    }
  };
  const back = () => {
    const last = expansions[expansions.length - 1];
    setExpansions((list) => list.slice(0, -1));
    if (last && selected !== null && last.nodes.some((n) => n.id === selected)) setSelected(null);
  };
  const chosen = selected !== null ? data.byId.get(selected) : undefined;
  const entry = chosen ? { mode, source, onShow, node: chosen, connections: connectionsOf(hoods.get(chosen.id), chosen.id), onChip: (id: number) => void open(id), onCollect: collect, onClose: () => setSelected(null) } : null;
  return (
    <div class="net" data-testid="net" tabIndex={-1} ref={root} onKeyDown=[REDACTED]
      {failure ? <Failure failure={failure} onAwake={retry} /> : null}
      {!failure && base === null ? <Skeleton shape="card" /> : null}
      {!failure && base?.nodes.length === 0 ? <EmptyState icon={BookCalmIcon} words={T.net.empty} sentence={T.net.empty} testId="net-empty" /> : null}
      <div ref={stage} class="net__stage" data-no-pull="true" data-open={chosen ? "true" : undefined} hidden={!base || base.nodes.length === 0 || failure !== null}>
        <NetHeader line={growth.line} glow={found ? glowLine(found.nodes.length, found.truncated) : null} place={place} {...(onClear ? { onClear } : {})} {...(onInfo ? { onInfo } : {})} />
        {data.nodes.length > 0 ? (
          <NetMap nodes={data.nodes} links={data.links} places={data.places} glow={glow} selected={selected} focus={focus} fresh={fresh} wide={wide.value} onOpen={(id) => void open(id)} onBloom={(id) => void bloom(id)} onEmpty={() => setSelected(null)} {...(source === "knowledge" ? { onCollect: collect } : {})} control={control}>
            {expansions.length > 0 ? (
              <button type="button" class="net__back chip" data-testid="net-back" aria-label={T.net.backLabel} onClick={back}>
                {T.net.back}
              </button>
            ) : null}
          </NetMap>
        ) : null}
        {entry && wide.value ? <EntryPanel key=[REDACTED] {...entry} /> : null}
      </div>
      {entry && !wide.value ? <EntrySheet key=[REDACTED] {...entry} /> : null}
    </div>
  );
}

/** 6.5: the camera flies to fit a search's hits, and back to where it was when the field is cleared. */
function useSearchFlight(found: KnowledgeGraph | null, places: Map<number, { x: number; y: number }>, control: { current: CameraControl | null }, bounds: () => ReturnType<typeof boundsOf>): void {
  const saved = useRef<Camera | null>(null);
  useEffect(() => {
    const c = control.current;
    const b = bounds();
    if (!c || !b) return;
    if (found) {
      const points = found.nodes.map((n) => places.get(n.id)).filter((p): p is { x: number; y: number } => p !== undefined);
      const target = fitPoints(points, b, c.size());
      if (!target) return;
      saved.current ??= c.camera();
      c.fly(target, 400);
    } else if (saved.current) {
      c.fly(saved.current, 400);
      saved.current = null;
    }
  }, [found]);
}

