  const [hoods, setHoods] = useState<ReadonlyMap<number, KnowledgeGraph>>(new Map());
  const stage = useRef<HTMLDivElement>(null);
  const root = useRef<HTMLDivElement>(null);
  const control = useRef<CameraControl | null>(null);
  const aspect = useAspect(stage);
  const data = useMapData(base, aspect, grown, expansions, found);
  const growth = useGrowth(mode, data.shown, (nodes: GraphNode[], links: GraphLink[]) => setGrown((list) => [...list, arrivalsOf(nodes, links, data.regions, data.places)]), source);
  const before = growth.before ?? null;
  const fresh = useMemo(() => new Set(data.nodes.filter((n) => isNew(n, before) && !tapped.has(n.id)).map((n) => n.id)), [data.nodes, before, tapped]);
  const glow = useMemo(() => (found ? new Map(found.nodes.map((n) => [n.id, glowOf(n)] as const)) : null), [found]);
  const hits = useMemo(() => (found ? [...found.nodes].sort((a, b) => glowOf(b) - glowOf(a)).map((n) => n.id) : []), [found]);
