/**
 * T10_F375 „Das Netz als Karte“ (6.4, 6.6): the small, quiet line of the map. What Luna knows in
 * this mode („1.240 Einträge · 38 Felder · 12 neu seit gestern“, only with the capability
 * knowledge-graph-growth), or a search's glow line while his words glow. T10_F592 (universe U554):
 * the line lies on the map's top left corner, so the map keeps the whole height; it names the mode
 * when it is not the first one, and a glow line has a small × that empties the search. Where the
 * line does not fit, its „neu“ part goes first (screen readers still hear it); a word is never cut. On the phone the page's i
 * stands right after it (`info`, the app's InfoButton); on a wide window the i is in the bar (src/screens/Memory.tsx).
 */

import type { ComponentChildren } from "preact";
import { useLayoutEffect, useRef, useState } from "preact/hooks";
import { T } from "../../text";
import { CloseIcon } from "../icons";

/** The line without its last part when that part tells what is new; null when there is none. */
export function withoutNew(text: string): string | null {
  const parts = text.split(" · ");
  return parts.length > 1 && /\bneu\b/.test(parts[parts.length - 1]!) ? parts.slice(0, -1).join(" · ") : null;
}

export function NetHeader({ line, glow, place, onClear, info }: { line: string | null; glow: string | null; place?: string | null; onClear?: () => void; info?: ComponentChildren }) {
  const full = glow ?? (line && place ? `${place} · ${line}` : (line ?? place ?? ""));
  const short = glow ? null : withoutNew(full);
  const head = useRef<HTMLDivElement>(null);
  const measure = useRef<HTMLSpanElement>(null);
  const [fits, setFits] = useState(true);
  useLayoutEffect(() => {
    const box = head.current;
    if (!box || !short) return setFits(true);
    const check = () => {
      const gap = parseFloat(getComputedStyle(box).columnGap) || 0;
      const others = [...box.children].filter((el) => el.tagName === "BUTTON" || el.classList.contains("net__info")) as HTMLElement[];
      const room = box.clientWidth - others.reduce((sum, el) => sum + el.offsetWidth + gap, 0);
      setFits((measure.current?.offsetWidth ?? 0) <= room);
    };
    check();
    if (typeof ResizeObserver === "undefined") return;
    let frame = 0;
    const observer = new ResizeObserver(() => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(check);
    });
    observer.observe(box);
    return () => {
      cancelAnimationFrame(frame);
      observer.disconnect();
    };
  }, [full, short]);
  const cut = !fits && short !== null;
  return (
    <div class="net__head" ref={head} hidden={!full && !info}>
      <span class="net__measure" ref={measure} aria-hidden="true">
        {full}
      </span>
      {full ? (
        <p class="net__line" data-testid={glow ? "net-glow-line" : "net-stats"} role="status">
          {cut ? short : full}
          {cut ? <span class="visually-hidden">{full.slice(short.length)}</span> : null}
        </p>
      ) : null}
      {glow && onClear ? (
        <button type="button" class="net__clear" data-testid="net-clear" aria-label={T.net.clearSearch} title={T.net.clearSearch} onClick={onClear}>
          <CloseIcon />
        </button>
      ) : null}
      {onInfo ? (
        <button type="button" class="icon-button net__info" data-testid="memory-info" aria-label={T.info.open(T.net.page.infoTitle)} title={T.net.page.infoTitle} aria-haspopup="dialog" onClick={onInfo}>
          <InfoIcon />
        </button>
      ) : null}
    </div>
  );
}

/*
 * T10_F336 (the universe plan's U320), rebuilt by T10_F375 „Das Netz als Karte“: the tab Netz of
 * Wissen as a map. The family's plan style and docs/design.md: soft dots and thin lines, the
 * edition's one accent (--luna-accent: Luna's purple, Sol's orange, Gaia's green) for the regions'
 * tint, the dots, their halo and what is new, design tokens only, so light and dark both work.
 * The map fills the screen below the page's one row of navigation, edge to edge (T10_F592), so the net never scrolls the page; the map says
 * touch-action pan-y and none while a finger is down (data-held), and handles every finger itself.
 */

.knowledge-item__links {
  font-size: var(--luna-text-xs);
  color: var(--luna-text-muted);
}

/* ------------------------------------------------------------------ the screen (6.4) */

/* T10_F576: Gedächtnis, one column. T10_F592 (universe U554): one row of navigation (the segment,
   the magnifier, the filter) in the bar itself; on the net the page has no padding and no frame,
   and the map fills the rest from edge to edge. */
.memory {
  display: flex;
  flex-direction: column;
  gap: var(--luna-space-3);
}

/* On the phone the row is the bar: the back arrow, then the row across the rest; the title is
   for screen readers only. On a wide window the row stands after the title. */
.bar--row {
  gap: var(--luna-space-1);
  min-height: 0;
  padding: calc(var(--luna-safe-top) + 6px) var(--luna-space-2) 6px;
}

.bar--row > .bar__actions {
  flex: 1;
  min-width: 0;
}

.memory-nav {
  display: flex;
  flex: 1;
  min-width: 0;
  align-items: center;
  justify-content: flex-end;
  gap: var(--luna-space-1);
}

.memory-nav > .segment-bar {
  flex: 1;
  min-width: 0;
  margin: 0 var(--luna-space-1) 0 0;
}

.memory-nav__space {
  flex: 1;
}

/* A wide window: the segment a calm width before the icons, a little lower than the bar. */
.shell--wide .memory-nav > .segment-bar {
  flex: none;
  width: 300px;
}

.shell--wide .memory-nav .segment-bar__segment {
  min-height: 34px;
  padding: 3px 4px;
}

/* The phone: the words stay at 13 pixels at least and keep a little room to the track's edges. */
.memory-nav .segment-bar[data-fit] .segment-bar__segment {
  padding-left: 4px;
  padding-right: 4px;
}

.memory-nav .segment-bar[data-fit="tight"] .segment-bar__segment {
  font-size: 13px;
  letter-spacing: -0.01em;
}

/* The narrowest phones (320 pixels): the row gives up its gaps and its edge, never a touch target's size. */
@media (max-width: 359px) {
  .bar--row {
    gap: 0;
    padding-left: var(--luna-space-1);
    padding-right: var(--luna-space-1);
  }

  .memory-nav {
    gap: 0;
  }

  .memory-nav > .segment-bar {
    gap: 0;
    margin-right: 2px;
    padding: 2px;
  }

  .memory-nav .segment-bar[data-fit] .segment-bar__segment {
    padding-left: 3px;
    padding-right: 3px;
    letter-spacing: -0.02em;
  }
}

.memory-find {
  display: flex;
  align-items: center;
  gap: var(--luna-space-2);
}

.memory-find > .luna-field,
.memory-find > .luna-input {
  flex: 1;
  min-width: 0;
}

.memory-screen--net .screen__body {
  display: flex;
  flex-direction: column;
  padding: 0;
  overflow: hidden;
}

.screen__body > .memory[data-view="net"] {
  flex: 1;
  min-height: 0;
  max-width: none;
  width: 100%;
  margin: 0;
}

/* The filter: the app's pull-down (FilterMenu) as an icon like its neighbours, tinted in the accent
   while another mode than the first is chosen; a sealed mode's lock after its name. */
.memory-nav .filter-menu--icon .filter-menu__pill {
  width: 40px;
  min-height: 40px;
  border-radius: var(--luna-radius-md);
  background: transparent;
}

.memory-nav .filter-menu--icon .filter-menu__pill:hover {
  background: var(--luna-surface-hover);
  color: var(--luna-text);
}

.memory-nav .filter-menu--icon .filter-menu__pill[data-active="true"] {
  background: var(--luna-accent-soft);
  color: var(--luna-accent);
}

@media (pointer: coarse) {
  .memory-nav .filter-menu--icon .filter-menu__pill {
    width: 44px;
    min-height: 44px;
  }
}

.filter-menu__mark {
  display: inline-flex;
  margin-left: auto;
  color: var(--luna-text-faint);
}

.filter-menu__mark svg {
  width: 14px;
  height: 14px;
}

.filter-menu__note {
  margin-right: var(--luna-space-1);
  font-size: var(--luna-text-xs);
}

.net {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  outline: none;
}

/* The map's line on its top left corner, quiet, never taking a row of its own. */
.net__head {
  position: absolute;
  top: var(--luna-space-2);
  left: var(--luna-space-3);
  right: 64px;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: var(--luna-space-1);
  pointer-events: none;
}

.net__head[hidden] {
  display: none;
}

.net__line {
  min-width: 0;
  margin: 0 0 0 -6px;
  padding: 2px 6px;
  border-radius: var(--luna-radius-sm);
  background: color-mix(in srgb, var(--luna-bg) 82%, transparent);
  font-size: var(--luna-text-xs);
  color: var(--luna-text-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  font-variant-numeric: tabular-nums;
}

.net__clear {
  flex: none;
  display: inline-grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border: 0;
  border-radius: 50%;
  background: none;
  color: var(--luna-text-muted);
  cursor: pointer;
  pointer-events: auto;
}

.net__clear svg {
  width: 16px;
  height: 16px;
}

/* The page's i on the phone, right after the line: the app's (i) (U267) as a small sign with a
   whole finger's target. */
.icon-button.net__info {
  flex: none;
  width: 44px;
  height: 44px;
  margin: -8px 0 -8px -10px;
  border-radius: 50%;
  pointer-events: auto;
}

.net__info svg {
  width: 16px;
  height: 16px;
}

/* The line's whole width, measured out of sight (the „neu“ part goes when it does not fit). */
.net__measure {
  position: absolute;
  visibility: hidden;
  padding: 0 6px;
  white-space: nowrap;
  font-size: var(--luna-text-xs);
  font-variant-numeric: tabular-nums;
  pointer-events: none;
}

@media (pointer: coarse) {
  .net__clear {
    width: 44px;
    height: 44px;
    margin: -8px 0;
  }
}

.net__stage {
  position: relative;
  flex: 1;
  min-height: 240px;
  display: flex;
  background: var(--luna-bg);
  overflow: hidden;
}

.net__stage[hidden] {
  display: none;
}

.memory[data-view="net"] .net > .placeholder,
.memory[data-view="net"] .net > .empty-state,
.memory[data-view="net"] .net > .notice {
  margin: var(--luna-space-4);
}

/* ------------------------------------------------------------------ the map (6.1, 6.2) */

.net-map {
  position: relative;
  flex: 1;
  min-width: 0;
}

.net-map__svg {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  touch-action: pan-y;
  cursor: grab;
  user-select: none;
  -webkit-user-select: none;
  -webkit-touch-callout: none;
  outline: none;
}

.net-map__svg[data-held] {
  touch-action: none;
  cursor: grabbing;
}

/* The three tiers: far away (data-tier 1) the territories with their circles and names, their nodes
   drawn in as small light dots with their links as fine light lines (data-folded: they belong to
   a territory and a tap there flies into it), every node without a territory a small quiet dot
   with its links at a whisper; one step closer the nodes come out full above the territories and
   only the touched node's links speak. */
.net-map__svg[data-tier="1"] .net__node[data-folded]:not([data-state="glow"]):not([data-selected]) > circle {
  transform: scale(0.5);
}

.net-map__svg[data-tier="1"] .net__node[data-folded]:not([data-state="glow"]):not([data-selected]) .net__dot {
  fill-opacity: 1;
}

.net-map__svg[data-tier="1"] .net__link[data-folded]:not(.net__link--strong) {
  stroke: var(--luna-accent);
  stroke-opacity: 0.3;
}

/* Far away the dots and their lines stand light on the territories: the main colour, brightened as
   one layer (one filter for the whole group, not one per dot). */
.net-map__svg[data-tier="1"] .net__nodes,
.net-map__svg[data-tier="1"] .net__links {
  filter: brightness(1.6);
}

.net-map__svg[data-tier="1"] .net__link:not([data-folded]):not(.net__link--strong) {
  opacity: 0.4;
}

.net-map__svg[data-tier="1"] .net__node:not([data-folded]):not([data-state="glow"]):not([data-selected]) {
  opacity: 0.45;
}

.net-map__svg[data-tier="1"] .net__node:not([data-folded]):not([data-state="glow"]):not([data-selected]) > circle {
  transform: scale(0.6);
}

.net-map__svg[data-tier="1"] .net__dot {
  stroke: none;
}

.net-map__svg[data-tier="1"] .net__orbit {
  display: none;
}

.net__cluster {
  pointer-events: none;
}

/* T12_F788 (universe U717): a territory, flat in the edition's main colour: its fill's opacity by
   coverage (the path's fill-opacity, 0.18 to 0.45), its jagged border 1.5 px at 0.9, under the
   links and nodes. */
.net__territory-area {
  fill: var(--luna-accent);
  stroke: var(--luna-accent);
  stroke-opacity: 0.9;
  stroke-width: 1.5px;
  stroke-linejoin: miter;
  vector-effect: non-scaling-stroke;
  pointer-events: none;
}

/* Its soft glow along the border, and the light in its middle (lighter towards it). */
.net__territory-glow {
  fill: none;
  stroke: var(--luna-accent);
  stroke-opacity: 0.16;
  stroke-width: 7px;
  stroke-linejoin: round;
  vector-effect: non-scaling-stroke;
  pointer-events: none;
}

.net__territory-light {
  pointer-events: none;
}

.net__territory-stop {
  stop-color: var(--luna-accent-hover);
}

/* One step closer the links stay a whisper, except around the touched or chosen node. */
.net-map__svg[data-tier="2"] .net__link:not(.net__link--strong) {
  stroke-opacity: 0.035;
}

/* T10_F592: a solid flat disc in the accent, one fine ring around it, its count in the accent's
   text colour (readable in light and dark), its name below in the region names' one style. */
.net__cluster-ball {
  fill: var(--luna-accent);
}

.net__cluster-ring {
  fill: none;
  stroke: var(--luna-accent);
  stroke-opacity: 0.4;
  stroke-width: 1px;
}

.net__cluster-count {
  fill: var(--luna-accent-text);
  font-size: 12px;
  font-weight: var(--luna-weight-medium);
  text-anchor: middle;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.02em;
}

.net__link {
  stroke: var(--luna-text);
  stroke-width: 1px;
  vector-effect: non-scaling-stroke;
}

.net__links[data-dim] .net__link {
  stroke-opacity: 0.05;
}

.net__link--strong {
  stroke: var(--luna-accent);
  stroke-opacity: 0.8;
  stroke-width: 1.5px;
}

/* T10_F592: flat discs, a hairline in the map's colour between neighbours, one fine ring around a
   significant node, a flat soft disc behind a search's hit; no gradient, no light, no shadow. */
.net__dot {
  fill: var(--luna-accent);
  stroke: var(--luna-bg);
  stroke-width: 1px;
  vector-effect: non-scaling-stroke;
}

.net__node[data-state="dim"] .net__dot {
  fill: var(--luna-border-strong);
}

.net__orbit {
  fill: none;
  stroke: var(--luna-accent);
  stroke-opacity: 0.35;
  stroke-width: 1px;
  vector-effect: non-scaling-stroke;
  pointer-events: none;
}

.net__halo {
  fill: var(--luna-accent);
  fill-opacity: 0.16;
  pointer-events: none;
}

.net__ring {
  fill: none;
  stroke: var(--luna-accent);
  stroke-width: 2px;
  vector-effect: non-scaling-stroke;
  pointer-events: none;
}

.net__node[data-selected] .net__ring,
.net__node[data-focus] .net__ring {
  stroke: var(--luna-text);
}

/* 6.6: what is new since his last visit: a small accent dot. */
.net__new {
  fill: var(--luna-accent);
  stroke: var(--luna-bg);
  stroke-width: 1.5px;
  vector-effect: non-scaling-stroke;
}

.net__title,
.net__region-name {
  text-anchor: middle;
  paint-order: stroke;
  stroke: var(--luna-bg);
  stroke-linejoin: round;
  pointer-events: none;
}

.net__title {
  fill: var(--luna-text);
  font-size: var(--luna-text-xs);
  stroke-width: 3px;
}

/* A node's title sits on a soft backdrop in the page's colour, so it stays readable over dots. */
.net__title-back {
  fill: var(--luna-bg);
  fill-opacity: 0.82;
  pointer-events: none;
}

.net__region-name {
  fill: var(--luna-text);
  font-size: 14px;
  font-weight: var(--luna-weight-medium);
  stroke-width: 3px;
}

@media (min-width: 900px) {
  .net__title {
    font-size: 13px;
  }

  .net__region-name {
    font-size: 15px;
  }
}

.net__tip {
  position: absolute;
  transform: translate(-50%, -130%);
  padding: 2px var(--luna-space-2);
  border: 1px solid var(--luna-border);
  border-radius: var(--luna-radius-full);
  background: var(--luna-bg-raised);
  color: var(--luna-text-muted);
  font-size: var(--luna-text-xs);
  white-space: nowrap;
  pointer-events: none;
  z-index: 2;
}

.net__collect {
  position: absolute;
  transform: translateX(-50%);
  z-index: 2;
  background: var(--luna-bg-raised);
  color: var(--luna-text);
  box-shadow: var(--luna-shadow-md);
  white-space: nowrap;
}

/* Top right, so the entry's sheet on the phone never covers it. */
.net__zoom {
  position: absolute;
  top: var(--luna-space-2);
  right: var(--luna-space-2);
  display: flex;
  flex-direction: column;
  gap: var(--luna-space-1);
  z-index: 1;
}

.net__zoom-button {
  border: 1px solid var(--luna-border);
  background: var(--luna-bg-raised);
  box-shadow: var(--luna-shadow-sm);
}

.net__back {
  position: absolute;
  top: calc(var(--luna-space-2) + 30px);
  left: var(--luna-space-2);
  z-index: 1;
}

/* ------------------------------------------------------------------ the entry (6.3) */

.net-panel {
  flex: none;
  width: 320px;
  border-left: 1px solid var(--luna-border);
  background: var(--luna-surface);
  overflow-y: auto;
  padding: var(--luna-space-3) var(--luna-space-4);
  overflow-wrap: anywhere;
}

.net-panel__head {
  display: flex;
  align-items: flex-start;
  gap: var(--luna-space-2);
}

.net-panel__title {
  flex: 1;
  margin: var(--luna-space-2) 0;
  font-size: var(--luna-text-lg);
  font-weight: var(--luna-weight-bold);
}

/* The kit's sheet over the map: no dimming, so the map stays visible and movable above it. */
.net-sheet .luna-sheet-backdrop {
  display: none;
}

/* A peek of at most 45 % of the screen (SHEET_PEEK in KnowledgeNet.tsx), so the map stays visible
   above it; the kit's sheet cannot be dragged larger, its content scrolls inside instead. */
.net-sheet .luna-sheet {
  box-sizing: border-box;
  max-height: 45vh;
  max-height: 45dvh;
  overflow-wrap: anywhere;
}

@media (min-width: 768px) {
  .net-sheet .luna-sheet {
    left: 0;
    right: 0;
    top: auto;
    bottom: 0;
    width: auto;
    transform: none;
    border-radius: var(--luna-radius-xl) var(--luna-radius-xl) 0 0;
  }
}

.net-entry__meta,
.net-entry__kinds {
  margin: 0;
  font-size: var(--luna-text-xs);
  color: var(--luna-text-faint);
}

.net-entry__source {
  display: inline-block;
  margin-top: var(--luna-space-1);
  font-size: var(--luna-text-sm);
}

.net-entry__excerpt {
  margin: var(--luna-space-2) 0;
  font-size: var(--luna-text-sm);
}

.net-entry__links {
  margin: var(--luna-space-2) 0 0;
  font-size: var(--luna-text-sm);
  font-weight: var(--luna-weight-medium);
  color: var(--luna-accent);
}

.net-entry__chips {
  display: flex;
  flex-wrap: wrap;
  gap: var(--luna-space-1) var(--luna-space-2);
  margin: var(--luna-space-3) 0 0;
  padding: 0;
  list-style: none;
}

.net-entry__chips > li {
  max-width: 100%;
}

.net-entry__chip {
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  text-align: left;
}

.net-entry__chip-kind {
  color: var(--luna-text-faint);
}

@media (pointer: coarse) {
  .net-entry__chip,
  .net__collect,
  .net__back {
    min-height: 44px;
  }
}

